        TextView handle=text("━━━━━━━━",16,true);handle.setTextColor(Color.rgb(112,126,148));handle.setGravity(Gravity.CENTER);sheet.addView(handle);
        LinearLayout statusRow=row();statusView=text("Disconnected",13,false);statusView.setTextColor(Color.rgb(173,190,214));statusView.setTextIsSelectable(true);statusView.setOnClickListener(v->showConnectionDetails());statusRow.addView(statusView,new LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f));Button connectionDetails=smallButton("Details / proof");connectionDetails.setOnClickListener(v->showConnectionDetails());statusRow.addView(connectionDetails);sheet.addView(statusRow,margins(0,0,0,dp(7)));

        LinearLayout connectRow=row();fastestButton=smallButton("⚡ Fastest ▾");fastestButton.setContentDescription("Select the fastest measured Router VPN node or choose a specific node. Use Connect separately.");fastestButton.setOnClickListener(v->showFastConnectMenu());connectRow.addView(fastestButton);connectButton=primaryButton("Connect");connectButton.setOnClickListener(v->connectOrDisconnect());connectRow.addView(connectButton,new LinearLayout.LayoutParams(0,dp(50),1f));liveLatency=text("-- ms",11,true);liveLatency.setTextColor(Color.rgb(173,190,214));liveLatency.setGravity(Gravity.CENTER);liveLatency.setPadding(dp(6),0,dp(6),0);connectRow.addView(liveLatency);killSwitch=new CheckBox(this);killSwitch.setText("Kill");killSwitch.setContentDescription("Kill switch");killSwitch.setTextColor(Color.WHITE);killSwitch.setButtonTintList(ColorStateList.valueOf(Color.rgb(123,104,255)));killSwitch.setOnCheckedChangeListener((b,on)->{if(!b.isPressed())return;setQuickKillSwitch(on);});connectRow.addView(killSwitch);forwardButton=smallButton("Forward");forwardButton.setContentDescription("Server port-forwarding master");forwardButton.setOnClickListener(v->showForwarding());connectRow.addView(forwardButton);sheet.addView(connectRow);

