    private void applySheetWeight(){LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)sheet.getLayoutParams();p.weight=sheetExpanded?0.70f:0.44f;sheet.setLayoutParams(p);LinearLayout.LayoutParams m=(LinearLayout.LayoutParams)mapView.getLayoutParams();m.weight=sheetExpanded?0.30f:0.56f;mapView.setLayoutParams(m);}
    private void refreshAll(){refreshNodes();refreshModeChoices();refreshConnectionState();refreshSettingsState();refreshDnsSelection();refreshMultihopSummary();refreshTelemetry(false);refreshForwardingState();}
    private boolean mutationBusy(){return AndroidVpnMutationGuard.isBusy(this)||(viaEntryProbe!=null&&viaEntryProbe.isBusy());}
    private void refreshConnectionLater(){mapView.postDelayed(this::refreshAll,350);mapView.postDelayed(this::refreshAll,1300);mapView.postDelayed(this::refreshAll,3000);}

    private void connectOrDisconnect(){if(viaEntryProbe.isBusy()){toast("Via-entry candidate RTT is still being measured; the temporary entry will disconnect automatically first.");return;}if(connection.isActiveOrTransitioning()){statusView.setText("Disconnecting…");connectButton.setText("Disconnecting…");connection.disconnect(callback());return;}AndroidUnifiedNodeCatalog.Item selected=selectedCatalogItem();if(selected==null){showNodes();return;}if(!selected.isRouterVpn()){Intent intent=new Intent(this,StandardExitActivity.class);intent.putExtra(StandardExitActivity.EXTRA_EXIT_ID,selected.id);startActivity(intent);return;}if(multihopToggle.isChecked()){try{AndroidNodeStore.Node entry=nodeById(prefs().getString(MULTI_ENTRY,"")),exit=nodeById(prefs().getString(MULTI_EXIT,""));String exitMode=prefs().getString(MULTI_MODE,"");if(entry==null||exit==null||exitMode.isEmpty()){configureMultihop();return;}statusView.setText("Preparing multihop…");connection.connectMultihop(entry,exit,exitMode,callback());}catch(Exception error){toast(safe(error));}return;}ModeChoice choice=currentMode();if(choice==null){refreshModeChoices();choice=currentMode();if(choice==null)return;}statusView.setText("Preparing "+choice.title+"…");connection.connect(choice.id,choice.layers,callback());}
    private AndroidUnifiedConnectionController.Callback callback(){return new AndroidUnifiedConnectionController.Callback(){public void progress(String message){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;statusView.setText(message);connectButton.setText("Disconnect");});}public void finished(boolean ok,String message){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;statusView.setText(message);if(!ok)toast(message);refreshAll();refreshConnectionLater();});}};}
    private void refreshConnectionState(){boolean active=connection!=null&&connection.isActiveOrTransitioning(),busy=mutationBusy();connectButton.setText(active?"Disconnect":"Connect");nodeButton.setEnabled(!busy);fastestButton.setEnabled(!busy);killSwitch.setEnabled(!busy);multihopToggle.setEnabled(!busy);modeSpinner.setEnabled(!busy);dnsSpinner.setEnabled(!busy);if(!viaEntryProbe.isBusy())statusView.setText(AndroidHomeSummary.format(this,nodeStore));if(!connection.isConnected()){currentPathMs=0;liveLatency.setText("-- ms");}}

    private void showConnectionDetails(){String truth=AndroidHomeSummary.format(this,nodeStore);new AlertDialog.Builder(this).setTitle("Connection details & proof").setMessage(truth+"\n\nConnected is not treated as a proved public exit until the current app-owned VPN network, frozen session node/path and current-session exit proof all agree.").setPositiveButton("Prove actual exit",(d,w)->{statusView.setText("Proving actual public VPN exit for this session…");AndroidHomeSummary.proveActualExit(this,nodeStore,(message,error)->runOnUiThread(()->{statusView.setText(message);if(error!=null)toast(message);refreshAll();}));}).setNeutralButton("Emergency disconnect",(d,w)->{statusView.setText("Emergency disconnect requested…");AndroidHomeSummary.emergencyDisconnect(this,(message,error)->runOnUiThread(()->{statusView.setText(message);if(error!=null)toast(message);refreshAll();refreshConnectionLater();}));}).setNegativeButton("Close",null).show();}

    private void showFastConnectMenu(){if(mutationBusy()){toast("Disconnect/finish the current VPN operation before changing the selected fastest node.");return;}fastestButton.setEnabled(false);fastestButton.setText("Testing…");telemetry.measureAll(3,(values,error)->runOnUiThread(()->{fastestButton.setEnabled(true);refreshNodes();if(error!=null){toast("Fastest-node test failed: "+safe(error));return;}if(values==null||values.isEmpty()){toast("No measurable Router VPN nodes are available.");return;}String[]labels=new String[values.size()+1];labels[0]="⚡ Fastest — "+values.get(0).name+" • "+values.get(0).shortLabel();for(int i=0;i<values.size();i++)labels[i+1]=values.get(i).name+" • "+values.get(i).shortLabel();new AlertDialog.Builder(this).setTitle("Select node").setMessage("Live TCP RTT is lightweight. Selecting a target does not connect; use the separate Connect button when ready. The 50-sample Performance test remains the durable benchmark.").setItems(labels,(d,w)->{if(mutationBusy()){toast("VPN state changed while Fastest was measuring; disconnect/finish before selecting another node.");return;}AndroidTelemetry.Result pick=values.get(w==0?0:w-1);try{nodeStore.select(pick.id);prefs().edit().putString(SELECTED_KIND,"router-vpn").putString(SELECTED_ID,pick.id).apply();refreshAll();toast("Selected "+pick.name+". Press Connect when ready.");}catch(Exception e){toast(safe(e));}}).setNegativeButton("Cancel",null).show();}));}

    private void refreshTelemetry(boolean force){long now=System.currentTimeMillis();if(telemetryBusy||viaEntryProbe.isBusy()||(!force&&now-lastTelemetryAt<1800))return;lastTelemetryAt=now;AndroidHomeStateStore.Snapshot home=AndroidHomeStateStore.snapshot(this);boolean connected=connection!=null&&connection.isConnected()&&!"external".equals(home.logicalMode);if(connected){telemetryBusy=true;telemetry.currentPath(2,(path,error)->runOnUiThread(()->{telemetryBusy=false;if(error==null&&path!=null){currentPathMs=path.medianMs;liveLatency.setText(String.format(Locale.US,"%.1f ms",path.medianMs));}else{currentPathMs=0;liveLatency.setText("-- ms");}refreshMultihopSummary();}));}else{currentPathMs=0;liveLatency.setText("-- ms");}refreshMultihopTelemetry();}
    private void refreshMultihopTelemetry(){String entryId,exitId;if(connection.isMultihopConnected()){entryId=connection.activeMultihopEntryId();exitId=connection.activeMultihopExitId();}else{if(!prefs().getBoolean(MULTI_ON,false))return;entryId=prefs().getString(MULTI_ENTRY,"");exitId=prefs().getString(MULTI_EXIT,"");}try{AndroidNodeStore.Node entry=nodeById(entryId),exit=nodeById(exitId);if(entry==null||exit==null)return;if(telemetry.cachedMedian(entry.id)<=0)telemetry.measureNode(entry,2,(r,e)->runOnUiThread(()->{refreshMap();refreshMultihopSummary();}));if(telemetry.cachedMedian(exit.id)<=0)telemetry.measureNode(exit,2,(r,e)->runOnUiThread(()->{refreshMap();refreshMultihopSummary();}));}catch(Exception ignored){}}

    private void showPerformance(){String[]actions={"Live current tunnel RTT","50-sample selected node","Benchmark all Router nodes","Real current VPN path speed","Routed multihop speeds","Path throughput / Auto MTU status"};new AlertDialog.Builder(this).setTitle("Performance").setMessage("RTT and Mbps are separate real measurements. Real path speed transfers 8 MiB down and 8 MiB up against the authenticated private router-agent through Android's active VPN route. Routed multihop speed independently contacts each actual live hop through the current routing graph; unreachable hops remain unavailable rather than being derived from RTT arithmetic.").setItems(actions,(d,w)->{if(w==0){if(!connection.isConnected()){toast("Connect first for current tunnel RTT.");return;}telemetry.currentPath(5,(r,e)->runOnUiThread(()->dialog("Live tunnel RTT",e==null&&r!=null?String.format(Locale.US,"Median %.1f ms • %d ok / %d failed\n%s",r.medianMs,r.samples,r.failed,r.proof):safe(e))));}else if(w==1){try{AndroidNodeStore.Node n=nodeById(nodeStore.activeId());if(n==null)throw new IllegalStateException("Select a Router VPN node first.");toast("Running 50 samples…");telemetry.measureNode(n,50,(r,e)->runOnUiThread(()->{if(e!=null)toast(safe(e));else{dialog("50-sample node benchmark",r.detail());refreshMap();}}));}catch(Exception e){toast(safe(e));}}else if(w==2){toast("Benchmarking linked Router nodes…");telemetry.measureAll(5,(values,e)->runOnUiThread(()->{if(e!=null){toast(safe(e));return;}StringBuilder out=new StringBuilder();for(AndroidTelemetry.Result r:values)out.append(r.detail()).append('\n');dialog("Node benchmark",out.toString());refreshMap();}));}else if(w==3){if(!connection.isConnected()){toast("Connect Router VPN before testing current path speed.");return;}toast("Testing 8 MiB down + 8 MiB up through the active VPN path…");telemetry.speedTest(8<<20,(r,e)->runOnUiThread(()->{if(e!=null)dialog("Real VPN path speed",safe(e));else dialog("Real VPN path speed",r.detail()+"\n\nProof: authenticated bounded private router-agent transfer through the frozen current Android VPN session path.");}));}else if(w==4){runRoutedHopSpeeds();}else{JSONObject p=activeRouterProfile();if(p==null){toast("Select a Router VPN node first.");return;}double mbps=p.optDouble("effective_mtu_mbps",0),rtt=p.optDouble("effective_mtu_median_rtt_ms",0);int mtu=p.optInt("effective_mtu",0);String value=mbps>0?String.format(Locale.US,"Last MTU-path optimizer result: %.1f Mbps • MTU %d • RTT %.1f ms\n\nThis is separate from the real 8 MiB down/up path speed test.",mbps,mtu,rtt):"No proven Auto-MTU optimizer result is stored for this path yet. Open Settings / MTU to configure Auto or Fixed MTU. Real path Mbps is a separate Performance action.";dialog("Path throughput / Auto MTU",value);}}).setNegativeButton("Close",null).show();}

    private void runRoutedHopSpeeds(){
        if(!connection.isMultihopConnected()){toast("Connect the actual Android multihop graph before testing routed hop speeds.");return;}
        try{
            AndroidNodeStore.Node entry=nodeById(connection.activeMultihopEntryId()),exit=nodeById(connection.activeMultihopExitId());
            if(entry==null||exit==null||entry.id.equals(exit.id))throw new IllegalStateException("Active multihop graph identity is unavailable.");
            toast("Testing routed entry and exit hop speeds…");
            telemetry.speedTest(entry,8<<20,(entryResult,entryError)->telemetry.speedTest(exit,8<<20,(exitResult,exitError)->runOnUiThread(()->{
                String entryText=entryError==null&&entryResult!=null?entryResult.detail():"Unavailable: "+safe(entryError);
                String exitText=exitError==null&&exitResult!=null?exitResult.detail():"Unavailable: "+safe(exitError);
                dialog("Routed multihop speeds","ENTRY • "+entry.name+"\n"+entryText+"\n\nEXIT • "+exit.name+"\n"+exitText+"\n\nProof: each row independently contacts that exact runtime hop's authenticated private router-agent through the live Android VPN routing graph. These values are not inferred segment bandwidth.");
            })));
        }catch(Exception error){toast(safe(error));}
    }

    private void refreshModeChoices(){String wanted=prefs().getString(MODE_KEY,"smart-auto");List<ModeChoice> values=new ArrayList<>();values.add(new ModeChoice("smart-auto","SMART AUTO — recommended"));values.add(new ModeChoice("auto","AUTO — first proven path"));try{JSONObject root=activeBundle();JSONArray logical=root.optJSONArray("logicalModes");if(logical!=null)for(int i=0;i<logical.length();i++){JSONObject m=logical.optJSONObject(i);if(m==null)continue;String id=m.optString("id","");if(id.isEmpty())continue;values.add(new ModeChoice(id,m.optString("name",id)));}}catch(Exception ignored){}for(CustomPreset p:loadCustomPresets())values.add(new ModeChoice("custom:"+p.name,"CUSTOM • "+p.name,p.layers));values.add(new ModeChoice("custom:new","New CUSTOM preset…"));modeChoices=values;ArrayAdapter<ModeChoice> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);modeSpinner.setAdapter(adapter);int index=0;for(int i=0;i<values.size();i++)if(values.get(i).id.equals(wanted)){index=i;break;}modeSpinner.setSelection(index,false);modeSpinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){boolean ready;public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int pos,long id){if(!ready){ready=true;return;}if(pos<0||pos>=modeChoices.size())return;if(mutationBusy()){toast("Disconnect/finish the current VPN operation before changing the next connection mode or CUSTOM preset.");refreshModeChoices();return;}ModeChoice selected=modeChoices.get(pos);if("custom:new".equals(selected.id)){showCustomBuilder(null);return;}prefs().edit().putString(MODE_KEY,selected.id).apply();modeHint.setText(selected.id.startsWith("custom:")?"Saved visual CUSTOM preset • exact required layers":"Unavailable presets remain visible; the engine fails closed with the exact readiness/proof reason.");}});}
    private ModeChoice currentMode(){if(modeSpinner==null||modeChoices.isEmpty())return null;int i=modeSpinner.getSelectedItemPosition();return i>=0&&i<modeChoices.size()?modeChoices.get(i):modeChoices.get(0);}
    private void showCustomBuilder(CustomPreset editing){if(mutationBusy()){toast("Disconnect/finish the current VPN operation before creating, editing or deleting CUSTOM presets.");return;}try{List<String> layers=allCatalogLayers();if(layers.isEmpty()){toast("No mode layers are available in the selected Router VPN bundle.");return;}LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(8),dp(18),0);EditText name=new EditText(this);name.setHint("Preset name");if(editing!=null)name.setText(editing.name);body.addView(name);body.addView(text("Select exact required layers. Router VPN tries only native Android stacks containing every selected layer and fails closed if no compatible path passes proof.",12,false));boolean[] checked=new boolean[layers.size()];Set<String> old=editing==null?Collections.emptySet():new LinkedHashSet<>(editing.layers);for(int i=0;i<layers.size();i++)checked[i]=old.contains(layers.get(i));AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(editing==null?"New CUSTOM preset":"Edit CUSTOM • "+editing.name).setView(body).setMultiChoiceItems(layers.toArray(new CharSequence[0]),checked,(d,w,on)->checked[w]=on).setPositiveButton("Save",null).setNeutralButton(editing==null?"Cancel":"Delete",null).setNegativeButton("Cancel",null);AlertDialog dialog=b.create();dialog.setOnShowListener(x->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(mutationBusy()){toast("VPN state changed; disconnect/finish before saving CUSTOM presets.");return;}String n=name.getText().toString().trim();List<String> selected=new ArrayList<>();for(int i=0;i<checked.length;i++)if(checked[i])selected.add(layers.get(i));if(n.isEmpty()||n.length()>64){toast("Preset name must be 1–64 characters.");return;}if(selected.isEmpty()){toast("CUSTOM requires at least one layer.");return;}saveCustomPreset(new CustomPreset(n,selected),editing==null?null:editing.name);prefs().edit().putString(MODE_KEY,"custom:"+n).apply();dialog.dismiss();refreshModeChoices();});if(editing!=null)dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{if(mutationBusy()){toast("VPN state changed; disconnect/finish before deleting CUSTOM presets.");return;}deleteCustomPreset(editing.name);prefs().edit().putString(MODE_KEY,"smart-auto").apply();dialog.dismiss();refreshModeChoices();});});dialog.show();}catch(Exception error){toast("CUSTOM builder unavailable: "+safe(error));}}

    private void refreshNodes(){if(catalog==null||mapView==null)return;try{List<AndroidUnifiedNodeCatalog.Item>items=catalog.list(AndroidUnifiedNodeCatalog.SORT_CURRENT);String selectedKind=prefs().getString(SELECTED_KIND,"router-vpn"),selectedId=prefs().getString(SELECTED_ID,nodeStore.activeId());if(selectedId.isEmpty()&&!items.isEmpty()&&!mutationBusy()){AndroidUnifiedNodeCatalog.Item first=items.get(0);selectedKind=first.kind;selectedId=first.id;if(first.isRouterVpn())nodeStore.select(first.id);prefs().edit().putString(SELECTED_KIND,selectedKind).putString(SELECTED_ID,selectedId).apply();}List<RouterVpnNodeMapView.Marker>markers=new ArrayList<>();String entry,exit;boolean multi;if(connection.isMultihopConnected()){entry=connection.activeMultihopEntryId();exit=connection.activeMultihopExitId();multi=true;}else{entry=prefs().getString(MULTI_ENTRY,"");exit=prefs().getString(MULTI_EXIT,"");multi=prefs().getBoolean(MULTI_ON,false);}AndroidUnifiedNodeCatalog.Item chosen=null;for(AndroidUnifiedNodeCatalog.Item item:items){if(item.kind.equals(selectedKind)&&item.id.equals(selectedId))chosen=item;if(!item.hasCoordinates())continue;String role;if(multi&&item.isRouterVpn()&&item.id.equals(entry))role=RouterVpnNodeMapView.ROLE_ENTRY;else if(multi&&item.isRouterVpn()&&item.id.equals(exit))role=RouterVpnNodeMapView.ROLE_EXIT;else if(item.id.equals(selectedId)&&item.kind.equals(selectedKind))role=RouterVpnNodeMapView.ROLE_SELECTED;else if(!item.isRouterVpn())role=RouterVpnNodeMapView.ROLE_EXTERNAL;else role=RouterVpnNodeMapView.ROLE_NORMAL;double ms=telemetry==null?0:telemetry.cachedMedian(item.id);if(ms<=0&&item.hasMeasuredLatency())ms=item.latencyMedianMs;markers.add(new RouterVpnNodeMapView.Marker(item.kind+":"+item.id,item.name,item.latitude,item.longitude,role,ms));}mapView.setMarkers(markers);nodeButton.setText(chosen==null?"Add / select node":(chosen.isRouterVpn()?"Router • ":"Custom • ")+chosen.name+(telemetry!=null&&telemetry.cachedMedian(chosen.id)>0?String.format(Locale.US," • %.1f ms",telemetry.cachedMedian(chosen.id)):"")+"  ▾");if(fastestButton!=null)fastestButton.setText(chosen==null?"⚡ Fastest ▾":"⚡ "+chosen.name+" ▾");}catch(Exception error){nodeButton.setText("Node catalog unavailable");if(fastestButton!=null)fastestButton.setText("⚡ Fastest ▾");mapView.setMarkers(new ArrayList<>());}}
