    private void showProfileManager(){try{List<AndroidNodeStore.Node>nodes=nodeStore.list();if(nodes.isEmpty()){new AlertDialog.Builder(this).setTitle("Profiles").setMessage("No Router VPN profiles are stored. Pair/import one, or open Custom exits for standard external profiles.").setPositiveButton("Add Router",(d,w)->showPairDialog()).setNeutralButton("Custom exits",(d,w)->openStandardExits()).setNegativeButton("Close",null).show();return;}String[]labels=new String[nodes.size()];for(int i=0;i<nodes.size();i++)labels[i]=(nodes.get(i).id.equals(nodeStore.activeId())?"✓ ":"")+nodes.get(i).name+(telemetry.cachedMedian(nodes.get(i).id)>0?String.format(Locale.US," • %.1f ms",telemetry.cachedMedian(nodes.get(i).id)):"");new AlertDialog.Builder(this).setTitle("Router profiles").setMessage("Select, update/re-pair, benchmark or delete. Re-pairing the same stable node identity updates its stored profile rather than creating a duplicate. Live sessions freeze profile identity until disconnect.").setItems(labels,(d,w)->showProfileActions(nodes.get(w))).setPositiveButton("Add / update via pairing",(d,w)->showPairDialog()).setNeutralButton("Custom profiles",(d,w)->openStandardExits()).setNegativeButton("Close",null).show();}catch(Exception e){toast(safe(e));}}
    private void showProfileActions(AndroidNodeStore.Node node){String[]a={"Select","50-sample benchmark","Update / re-pair","Delete"};new AlertDialog.Builder(this).setTitle(node.name).setItems(a,(d,w)->{try{if(w==0){if(mutationBusy()){toast("Disconnect/finish before selecting another Router profile.");return;}nodeStore.select(node.id);prefs().edit().putString(SELECTED_KIND,"router-vpn").putString(SELECTED_ID,node.id).apply();refreshAll();}else if(w==1){toast("Running 50 samples…");telemetry.measureNode(node,50,(r,e)->runOnUiThread(()->{if(e!=null)toast(safe(e));else{dialog("Profile benchmark",r.detail());refreshAll();}}));}else if(w==2)showPairDialog();else new AlertDialog.Builder(this).setTitle("Delete "+node.name+"?").setMessage("Only this app-private Router VPN profile is removed.").setPositiveButton("Delete",(x,y)->{if(mutationBusy()){toast("Disconnect/finish before deleting a Router profile.");return;}try{nodeStore.remove(node.id);refreshAll();}catch(Exception e){toast(safe(e));}}).setNegativeButton("Cancel",null).show();}catch(Exception e){toast(safe(e));}}).setNegativeButton("Close",null).show();}

    private void configureMultihop(){if(mutationBusy()){toast("Disconnect/finish the current VPN operation before editing multihop hops.");return;}try{List<AndroidNodeStore.Node>nodes=nodeStore.list();if(nodes.size()<2){toast("Multihop needs at least two different Router VPN nodes.");return;}String[]labels=new String[nodes.size()];for(int i=0;i<nodes.size();i++)labels[i]=nodes.get(i).name+(telemetry.cachedMedian(nodes.get(i).id)>0?String.format(Locale.US," • direct %.1f ms",telemetry.cachedMedian(nodes.get(i).id)):"");new AlertDialog.Builder(this).setTitle("Multihop entry").setMessage("Choose hop 1. Router VPN will then briefly establish and prove this entry so candidate hop-2 RTTs are measured through it, not calculated from direct RTTs.").setItems(labels,(d,w)->prepareViaEntryExitMeasurement(nodes.get(w),nodes)).setNegativeButton("Cancel",null).show();}catch(Exception error){toast(safe(error));}}
    private void prepareViaEntryExitMeasurement(AndroidNodeStore.Node entry,List<AndroidNodeStore.Node>all){if(mutationBusy()){toast("VPN state changed; disconnect/finish before measuring multihop candidates.");return;}List<AndroidNodeStore.Node>exits=new ArrayList<>();for(AndroidNodeStore.Node n:all)if(!n.id.equals(entry.id))exits.add(n);if(exits.isEmpty()){toast("No different exit nodes are available.");return;}pendingProbeEntryId=entry.id;pendingProbeCandidateIds=new ArrayList<>();for(AndroidNodeStore.Node n:exits)pendingProbeCandidateIds.add(n.id);Intent permission=VpnService.prepare(this);if(permission!=null){statusView.setText("Waiting for Android VPN permission to measure "+entry.name+" → candidate RTT…");startActivityForResult(permission,PREPARE_VIA_ENTRY_RTT);}else runPendingViaEntryProbe();}
    private void runPendingViaEntryProbe(){if(mutationBusy()&&!viaEntryProbe.isBusy()){clearPendingProbe();toast("VPN state changed while permission was open; disconnect/finish before measuring multihop candidates.");refreshAll();return;}AndroidNodeStore.Node entry=quietNode(pendingProbeEntryId);List<AndroidNodeStore.Node> exits=quietNodes(pendingProbeCandidateIds);if(entry==null||exits.isEmpty()){clearPendingProbe();toast("Multihop candidate measurement state expired; choose the entry again.");return;}statusView.setText("Preparing real "+entry.name+" → candidate RTT measurement…");viaEntryProbe.measure(entry,exits,5,new AndroidViaEntryLatencyProbe.Callback(){public void progress(String message){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())statusView.setText(message);});}public void finished(AndroidNodeStore.Node measuredEntry,List<AndroidTelemetry.Result>values,Throwable error){runOnUiThread(()->{List<AndroidNodeStore.Node>currentExits=quietNodes(pendingProbeCandidateIds);clearPendingProbe();if(isFinishing()||isDestroyed())return;refreshAll();showViaEntryExitPicker(measuredEntry,currentExits,values,error);});}});}
    private void showViaEntryExitPicker(AndroidNodeStore.Node entry,List<AndroidNodeStore.Node>exits,List<AndroidTelemetry.Result>values,Throwable measurementError){if(entry==null||exits==null||exits.isEmpty()){toast("Multihop candidate exits are unavailable.");return;}Map<String,AndroidTelemetry.Result>byId=new HashMap<>();if(values!=null)for(AndroidTelemetry.Result r:values)byId.put(r.id,r);String[]labels=new String[exits.size()];for(int i=0;i<exits.size();i++){AndroidTelemetry.Result r=byId.get(exits.get(i).id);labels[i]=entry.name+" → "+exits.get(i).name+" • "+(r==null?"unavailable":String.format(Locale.US,"%.1f ms",r.medianMs));}String note=measurementError==null?"Each RTT was measured while a proven temporary WireGuard tunnel to the selected entry was actually routing the device. That temporary tunnel is already disconnected. Values are not saved as direct-node RTTs.":"Via-entry RTT could not be proven: "+safe(measurementError)+"\n\nCandidates remain selectable, but Router VPN shows ‘unavailable’ instead of substituting direct RTT arithmetic.";new AlertDialog.Builder(this).setTitle("Multihop hop 2 • live via "+entry.name).setMessage(note).setItems(labels,(d,w)->chooseMultihopMode(entry,exits.get(w))).setNegativeButton("Cancel",null).show();}
    private void clearPendingProbe(){pendingProbeEntryId="";pendingProbeCandidateIds.clear();}
    private AndroidNodeStore.Node quietNode(String id){try{return nodeById(id);}catch(Exception ignored){return null;}}
    private List<AndroidNodeStore.Node> quietNodes(List<String> ids){List<AndroidNodeStore.Node>out=new ArrayList<>();if(ids==null)return out;try{List<AndroidNodeStore.Node>all=nodeStore.list();for(String id:ids)for(AndroidNodeStore.Node node:all)if(node.id.equals(id)){out.add(node);break;}}catch(Exception ignored){}return out;}
    private void chooseMultihopMode(AndroidNodeStore.Node entry,AndroidNodeStore.Node exit){if(mutationBusy()){toast("VPN state changed; disconnect/finish before editing multihop.");return;}try{List<NativeSingBoxController.ModeInfo>modes=connection.supportedMultihopExitModes(exit);if(modes.isEmpty()){toast("That exit has no proven Android Shadowsocks/Hysteria2 multihop transport.");return;}String[]labels=new String[modes.size()];for(int i=0;i<modes.size();i++)labels[i]=modes.get(i).name+" ["+modes.get(i).id+"]";new AlertDialog.Builder(this).setTitle("Exit transport").setItems(labels,(d,w)->{if(mutationBusy()){toast("VPN state changed; disconnect/finish before saving multihop.");return;}prefs().edit().putBoolean(MULTI_ON,true).putString(MULTI_ENTRY,entry.id).putString(MULTI_EXIT,exit.id).putString(MULTI_MODE,modes.get(w).id).apply();multihopToggle.setChecked(true);telemetry.measureNode(entry,3,(a,b)->runOnUiThread(this::refreshAll));telemetry.measureNode(exit,3,(a,b)->runOnUiThread(this::refreshAll));refreshAll();}).setNegativeButton("Cancel",null).show();}catch(Exception error){toast(safe(error));}}
    private void refreshMultihopSummary(){boolean live=connection.isMultihopConnected();boolean on=live||prefs().getBoolean(MULTI_ON,false);multihopToggle.setChecked(on);if(!on){multihopHint.setText("Off");return;}String entryId=live?connection.activeMultihopEntryId():prefs().getString(MULTI_ENTRY,""),exitId=live?connection.activeMultihopExitId():prefs().getString(MULTI_EXIT,""),mode=live?connection.activeMultihopExitMode():prefs().getString(MULTI_MODE,"");try{AndroidNodeStore.Node entry=nodeById(entryId),exit=nodeById(exitId);if(entry==null||exit==null){multihopHint.setText(live?"Live graph identity unavailable":"Choose hops");return;}double a=telemetry.cachedMedian(entry.id),b=telemetry.cachedMedian(exit.id);StringBuilder s=new StringBuilder(live?"LIVE • ":"").append(entry.name);if(a>0)s.append(String.format(Locale.US," %.1f ms",a));s.append(" → ").append(exit.name);if(b>0)s.append(String.format(Locale.US," %.1f ms",b));if(currentPathMs>0&&live)s.append(String.format(Locale.US," • PATH %.1f ms",currentPathMs));s.append(" • ").append(mode);multihopHint.setText(s.toString());}catch(Exception error){multihopHint.setText(live?"Live graph identity unavailable":"Choose hops");}}
    private AndroidNodeStore.Node nodeById(String id)throws Exception{if(id==null||id.isEmpty())return null;for(AndroidNodeStore.Node n:nodeStore.list())if(n.id.equals(id))return n;return null;}

