    private void refreshForwardingState(){AndroidHomeStateStore.Snapshot home=AndroidHomeStateStore.snapshot(this);if(viaEntryProbe.isBusy()||!connection.isConnected()||"external".equals(home.logicalMode)){forwardingEnabled=null;forwardButton.setText("Forward");return;}if(forwardingBusy)return;forwardingBusy=true;forwardingMaster.get((enabled,error)->runOnUiThread(()->{forwardingBusy=false;if(error==null&&enabled!=null){forwardingEnabled=enabled;forwardButton.setText(enabled?"Forward ON":"Forward OFF");}else{forwardingEnabled=null;forwardButton.setText("Forward ?");}}));}
    private void showForwarding(){if(viaEntryProbe.isBusy()){dialog("Master port forwarding","Via-entry candidate measurement is using a temporary Router VPN tunnel. It will disconnect automatically; forwarding is not changed during this probe.");return;}AndroidHomeStateStore.Snapshot home=AndroidHomeStateStore.snapshot(this);if(!connection.isConnected()){dialog("Master port forwarding","Connect a Router VPN home-node path first. The forwarding master is a real server-owned policy and is not changed while disconnected.");return;}if("external".equals(home.logicalMode)){dialog("Master port forwarding","A direct external exit does not own your Router VPN home-node forwarding policy. Connect a Router VPN home-node path first.");return;}if(forwardingBusy){toast("Forwarding master state is already being verified.");return;}forwardingBusy=true;forwardButton.setText("Forward …");forwardingMaster.get((enabled,error)->runOnUiThread(()->{forwardingBusy=false;if(error!=null||enabled==null){forwardingEnabled=null;forwardButton.setText("Forward ?");dialog("Master port forwarding","Could not verify the real forwarding-master state: "+safe(error));return;}forwardingEnabled=enabled;forwardButton.setText(enabled?"Forward ON":"Forward OFF");String state=enabled?"ON":"OFF";new AlertDialog.Builder(this).setTitle("Master port forwarding • "+state).setMessage("This is the real server forwarding master on the active Router VPN home node. It gates WAN→tunnel forwarding rules and Protected DMZ. The request is authenticated through the active VPN path; the Setup Center admin token never leaves the server.").setPositiveButton(enabled?"Turn OFF":"Turn ON",(d,w)->setForwardingMaster(!enabled)).setNeutralButton("Rules in Setup Center",(d,w)->dialog("Forwarding rules","The master switch is controlled here. Individual persistent rules and Protected DMZ remain server-owned in Setup Center so targets/owners/reserved ports can be validated safely.")).setNegativeButton("Close",null).show();}));}
    private void setForwardingMaster(boolean enabled){if(forwardingBusy)return;forwardingBusy=true;forwardButton.setText("Forward …");forwardingMaster.set(enabled,(actual,error)->runOnUiThread(()->{forwardingBusy=false;if(error!=null||actual==null){forwardingEnabled=null;forwardButton.setText("Forward ?");dialog("Forwarding update failed",safe(error));return;}forwardingEnabled=actual;forwardButton.setText(actual?"Forward ON":"Forward OFF");toast("Server port-forwarding master is now "+(actual?"ON":"OFF")+".");}));}

    private void setQuickDns(String mode){if(mutationBusy()){toast("Disconnect/finish before changing DNS.");refreshDnsSelection();return;}try{JSONObject root=activeBundle(),p=selectedProfile(root);if(p==null)throw new IllegalStateException("Select a Router VPN node first.");if("fastest".equals(mode)&&p.optString("fastest_dns_host","").trim().isEmpty()){AndroidProductParity.showDNS(this,nodeStore);return;}p.put("dns_mode",mode);if("home".equals(mode)){p.put("dns_protocol","udp");p.put("dns_port",53);p.put("dns_host",p.optString("adguard_ipv4",p.optString("adguard_ipv6","")));}nodeStore.importBundle(root.toString().getBytes(StandardCharsets.UTF_8));toast("DNS set to "+mode+" for the next tunnel; runtime proof still required.");}catch(Exception error){toast(safe(error));}refreshDnsSelection();}
